package com.muthumol.player.dummy;
import android.view.*;import android.media.AudioManager;import android.content.Context;import android.graphics.Rect;import android.widget.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class PlayerGestures {
 final PlayerActivity a;final GestureDetector detector;float x,y,brightness,originalSpeed;int volume;long startPosition,seekTarget;boolean eligible,sliding,horizontal,doublePending,holding;
 PlayerGestures(PlayerActivity a){this.a=a;detector=new GestureDetector(a,new GestureDetector.SimpleOnGestureListener(){public boolean onDown(MotionEvent e){return true;}public void onLongPress(MotionEvent e){if(eligible&&!sliding&&a.prefs.getBoolean("gestureHold",true)&&a.player!=null){holding=true;originalSpeed=a.player.getPlaybackParameters().speed;a.player.setPlaybackSpeed(2);feedback("Hold · 2×");}}public boolean onDoubleTap(MotionEvent e){doublePending=true;return true;}public boolean onDoubleTapEvent(MotionEvent e){if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;if(!doublePending||!eligible||sliding||holding||a.player==null||!a.prefs.getBoolean("gestureDouble",true))return false;doublePending=false;long delta=e.getX()<a.view.getWidth()/2f?-10000:10000;a.player.seekTo(clamp(a.player.getCurrentPosition()+delta));feedback(delta>0?"+10 seconds":"−10 seconds");return true;}});}
 long clamp(long p){long duration=a.player.getDuration();return Math.max(0,duration>0?Math.min(duration,p):p);}
 static boolean vertical(float dx,float dy,float threshold){return Math.abs(dy)>threshold&&Math.abs(dy)>Math.abs(dx)*1.5f;}
 boolean touch(MotionEvent e){if(a.player==null||e.getToolType(0)!=MotionEvent.TOOL_TYPE_FINGER||a.tvTools!=null&&a.tvTools.locked)return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();sliding=false;horizontal=false;holding=false;startPosition=a.player.getCurrentPosition();eligible=e.getPointerCount()==1&&!interactive(a.getWindow().getDecorView(),(int)e.getRawX(),(int)e.getRawY());AudioManager am=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);volume=am.getStreamVolume(AudioManager.STREAM_MUSIC);brightness=a.getWindow().getAttributes().screenBrightness;if(brightness<0)try{brightness=android.provider.Settings.System.getInt(a.getContentResolver(),android.provider.Settings.System.SCREEN_BRIGHTNESS)/255f;}catch(Exception ignored){brightness=.5f;}}
 if(e.getPointerCount()>1){eligible=false;if(holding){a.player.setPlaybackSpeed(originalSpeed);holding=false;}}
 if(eligible&&action==MotionEvent.ACTION_MOVE&&!holding){float dy=y-e.getY(),dx=e.getX()-x,threshold=Ui.dp(a,24);if(!sliding){horizontal=a.prefs.getBoolean("gestureHorizontal",true)&&Math.abs(dx)>threshold&&Math.abs(dx)>Math.abs(dy)*1.5f;boolean v=a.prefs.getBoolean("gestureVertical",true)&&vertical(dx,dy,threshold);if(horizontal||v){sliding=true;doublePending=false;MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);detector.onTouchEvent(cancel);cancel.recycle();}}
 if(sliding){if(horizontal){seekTarget=clamp(startPosition+(long)(dx/Math.max(1,a.view.getWidth())*120000));feedback("Seek · "+CinemaInfo.time(seekTarget));}else{float change=dy/Math.max(1,a.view.getHeight()*.7f);if(x>=a.view.getWidth()/2f){AudioManager am=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);int max=am.getStreamMaxVolume(AudioManager.STREAM_MUSIC),v=Math.max(0,Math.min(max,volume+Math.round(change*max)));am.setStreamVolume(AudioManager.STREAM_MUSIC,v,0);feedback("Volume "+Math.round(v*100f/Math.max(1,max))+"%");}else{WindowManager.LayoutParams p=a.getWindow().getAttributes();p.screenBrightness=Math.max(.02f,Math.min(1,brightness+change));a.getWindow().setAttributes(p);feedback("Brightness "+Math.round(p.screenBrightness*100)+"%");}}return true;}}
 boolean detected=eligible&&!sliding&&detector.onTouchEvent(e),consume=sliding||holding||detected;
 if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){if(holding){a.player.setPlaybackSpeed(originalSpeed);holding=false;}if(sliding&&horizontal&&action==MotionEvent.ACTION_UP)a.player.seekTo(seekTarget);if(action==MotionEvent.ACTION_CANCEL)eligible=false;}
 return consume;}
 boolean interactive(View v,int x,int y){if(v.getVisibility()!=View.VISIBLE)return false;Rect r=new Rect();if(!v.getGlobalVisibleRect(r)||!r.contains(x,y))return false;if(v instanceof Button||v instanceof ImageButton||v instanceof SeekBar||v instanceof androidx.media3.ui.DefaultTimeBar)return true;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=group.getChildCount()-1;i>=0;i--)if(interactive(group.getChildAt(i),x,y))return true;}return false;}
 void feedback(String text){if(a.seekFeedback!=null){a.seekFeedback.setText(text);a.seekFeedback.setVisibility(View.VISIBLE);a.ui.removeCallbacks(a.hideSeekFeedback);a.ui.postDelayed(a.hideSeekFeedback,1000);}}
 static void settings(PlayerActivity a){String[] keys={"gestureDouble","gestureVertical","gestureHorizontal","gestureHold"};String[] names={"Double tap ±10 seconds","Vertical volume / brightness","Horizontal seek","Hold for 2×"};String[] labels=new String[4];for(int i=0;i<4;i++)labels[i]=names[i]+" · "+a.prefs.getBoolean(keys[i],true);Ui.menu(a,"Phone gestures",labels,n->a.prefs.edit().putBoolean(keys[n],!a.prefs.getBoolean(keys[n],true)).apply());}
}
